import pickle, io, sys

class Dummy:
    def __init__(self, *a, **k): pass
    def __setstate__(self, s): pass

class SafeUnpickler(pickle.Unpickler):
    ALLOWED = {
        ('collections', 'OrderedDict'),
        ('numpy._core.multiarray', '_reconstruct'),
        ('numpy', 'ndarray'),
    }
    def find_class(self, module, name):
        if (module, name) in self.ALLOWED:
            if (module, name) == ('collections', 'OrderedDict'):
                import collections; return collections.OrderedDict
            return Dummy  # stub out numpy internals
        if module == 'numpy' and name == 'dtype':
            return Dummy
        raise RuntimeError(f'BLOCKED dangerous global: {module}.{name}')

def safe_load(fn):
    with open(fn, 'rb') as f:
        data = f.read()
    # check nothing after STOP
    obj = SafeUnpickler(io.BytesIO(data)).load()
    return obj

for i in range(1, 11):
    fn = f'model_{i:02d}.pkl'
    try:
        d = safe_load(fn)
        print(f\"{fn}: id={d.get('id')}, val_accuracy={d.get('val_accuracy')!r}, type={type(d.get('val_accuracy')).__name__}\")
    except Exception as e:
        print(f'{fn}: BLOCKED -> {e}')
""}
